const matchParens = (lst) => {
  const isGood = (s) => {
    let balance = 0;
    for (const ch of s) {
      if (ch === '(') balance++;
      else balance--;
      if (balance < 0) return false;
    }
    return balance === 0;
  };

  return isGood(lst[0] + lst[1]) || isGood(lst[1] + lst[0]) ? 'Yes' : 'No';
};
